if __name__ == "__main__":
    import sys

    if len(sys.argv) < 6:
        print("Usage: python checkout_engine.py <card_number> <exp_month> <exp_year> <cvv> <shop_url> [proxy_url]")
        sys.exit(1)

    card_num = sys.argv[1]
    exp_m = sys.argv[2]
    exp_y = sys.argv[3]
    cvv_code = sys.argv[4]
    shop = sys.argv[5]
    proxy = sys.argv[6] if len(sys.argv) > 6 else ""

    _load_proxy_pool_from_env()

    result = run_checkout_public(
        shop,
        f"{card_num}|{exp_m}|{exp_y}|{cvv_code}",
        proxy,
        True,
    )

    print(f"\n{'='*60}")
    print(f"  Card:        {result.get('card')}")
    print(f"  Status:      {result.get('status')}")
    print(f"  Status Code: {result.get('status_code')}")
    print(f"  Message:     {result.get('message')}")
    print(f"  Gateway:     {result.get('gateway')}")
    print(f"  Price:       {result.get('price')} {result.get('currency','')}")
    print(f"  Site:        {result.get('site')}")
    print(f"  Retryable:   {result.get('retryable')}")
    print(f"{'='*60}\n")

    ok = result.get('status') in ('Charged', 'Approved')
    sys.exit(0 if ok else 1)
